import{_ as a,c as s,o as t,af as p}from"./chunks/framework.zqhv3A7-.js";const d=JSON.parse('{"title":"AI Coding 时代，失效的不是 Git，而是 Git 工作流","description":"","frontmatter":{},"headers":[],"relativePath":"posts/最佳实践/AI Coding 时代，失效的不是 Git，而是 Git 工作流.md","filePath":"posts/最佳实践/AI Coding 时代，失效的不是 Git，而是 Git 工作流.md"}'),l={name:"posts/最佳实践/AI Coding 时代，失效的不是 Git，而是 Git 工作流.md"};function e(n,i,h,o,m,r){return t(),s("div",null,i[0]||(i[0]=[p(`<h1 id="ai-coding-时代-失效的不是-git-而是-git-工作流" tabindex="-1">AI Coding 时代，失效的不是 Git，而是 Git 工作流 <a class="header-anchor" href="#ai-coding-时代-失效的不是-git-而是-git-工作流" aria-label="Permalink to “AI Coding 时代，失效的不是 Git，而是 Git 工作流”">​</a></h1><h2 id="当前的-git-已经不适用于我们现在-ai-革命的形式了" tabindex="-1">当前的 Git 已经不适用于我们现在 AI 革命的形式了 <a class="header-anchor" href="#当前的-git-已经不适用于我们现在-ai-革命的形式了" aria-label="Permalink to “当前的 Git 已经不适用于我们现在 AI 革命的形式了”">​</a></h2><p>当前的 Git 已经不适用于我们现在 AI 革命的形式了。</p><p>更准确一点说，Git 不一定要删掉，它可以更新换代，我们依旧可以用 Git，但是需要新增一些新的命令、新的流程来适配。</p><p>首先明确一点，我们的 Git 不是为了解决多人协作的问题。多人协作本身不是问题，所以正确的描述应该是：<strong>Git 是多人协作的工具</strong>。</p><p>这个工具解决了多人协作的什么问题？这才是 Git 存在的意义。</p><p>以前没有协同工具的时候，多个人在一个代码仓库里面操作，怎么知道谁改了什么？怎么知道什么时候改的？怎么合并？怎么回退？怎么解决冲突？</p><p>Git 很好地解决了这些问题。</p><p>但是现在的问题变了。</p><p>我们需要知道以前没有协同工具的时候，多人协作在一个代码仓库如何进行操作。有了协同工具，它们又有什么样的问题，有什么样的痛点。只有总结出这两块，才真正知道 Git 现在面临的一个问题，也就是它解决的问题。</p><h2 id="ai-时代-commit-的价值正在下降" tabindex="-1">AI 时代，commit 的价值正在下降 <a class="header-anchor" href="#ai-时代-commit-的价值正在下降" aria-label="Permalink to “AI 时代，commit 的价值正在下降”">​</a></h2><p>我现在觉得，适配 Git 不重要，也是因为一些分支管理、一些 commit 的规范不重要了。</p><p>现在冲击最大的是 commit 的规范。</p><p>以前 commit 很重要。一个 commit message 写得好不好，能不能描述清楚这一次变更，是代码协作里面非常重要的一环。</p><p>但是现在不一样了。</p><p>现在很多代码都是 AI 生成的，人不一定真的看每一条 commit。即便它带着很清晰的 message，你也不一定明白这次 diff 背后的真实意图。</p><p>每天的 PR 和 commit 都有可能流于形式。</p><p>以前出现了 BUG，可以通过 Git 来看是谁改的，当初为什么改。现在还需要这个流程吗？我觉得这个问题是需要重新思考的。</p><p>因为 AI 生成的代码里，commit message 很可能只是“看起来规范”。它不一定真的承载了人的判断，也不一定真的能帮助下一个人理解这次修改。</p><p>所以我现在的判断是：</p><p><strong>commit 是代码账本，但它不应该再承担所有协作上下文。</strong></p><p>真正重要的东西从“每一条 commit 写得漂亮”，变成了：</p><ul><li>这次改动整体想解决什么问题？</li><li>AI 到底改了什么？</li><li>哪些地方需要人重点判断？</li><li>怎么验证它没有破坏以前的功能？</li><li>如果出问题，怎么知道这次变更的边界在哪里？</li></ul><p>也就是说，commit 的价值正在下降，意图和验证的价值正在上升。</p><h2 id="问题不是-git-而是-git-工作流太依赖程序员经验" tabindex="-1">问题不是 Git，而是 Git 工作流太依赖程序员经验 <a class="header-anchor" href="#问题不是-git-而是-git-工作流太依赖程序员经验" aria-label="Permalink to “问题不是 Git，而是 Git 工作流太依赖程序员经验”">​</a></h2><p>现在最矛盾的点是，Git 的 commit 这个流程没有必要承担那么多东西了。</p><p>其他的一些复杂多段协作流程也可能不重要。</p><p>它其实为了我们提交 MVP 的速度，可以极大地简化。</p><p>所有人都共用一个基线，只要知道哪个人开发的、什么时候开发的、这次改动解决什么问题、有没有影响以前的功能，这就可以了。</p><p>这也是因为我们现在的迭代不是双周了。它没有那么明确的概念，它甚至是两周的一个迭代、内部迭代、两天一个小版本、一天一个小版本。</p><p>所以我们要解决的问题就是：这两天或者一个大的版本，它有没有影响到以前的功能。</p><p>但是这跟 Git 有关系吗？</p><p>没有那么大关系。</p><p>这跟测试用例、单测、构建、验证流程有关。</p><p>Git 只是记录了代码历史，但它不能告诉你这个功能是不是还能用。它能告诉你谁改了文件，但它不能天然告诉你为什么这么改、怎么验证、风险在哪里。</p><h2 id="smart-commit-想解决什么问题" tabindex="-1">Smart Commit 想解决什么问题 <a class="header-anchor" href="#smart-commit-想解决什么问题" aria-label="Permalink to “Smart Commit 想解决什么问题”">​</a></h2><p>所以我想做的不是替代 Git，而是在 Git 上面加一层新的协作语义。</p><p>这个东西就是 Smart Commit。</p><p>Smart Commit 解决的问题不是“帮程序员少敲几个 git 命令”。如果只是这样，它的价值太低了。</p><p>它真正解决的是：</p><p><strong>在 AI Coding 时代，把一次代码提交从一堆 commit，变成一份可以被人理解的变更说明。</strong></p><p>以前我们可能会一次性提交十几条 commit。</p><p>但是这些意图、业务意图真的会有人看吗？</p><p>大概率不会。</p><p>真实场景里，人通常只看三样：</p><ul><li>最终 diff</li><li>PR 描述</li><li>CI、测试、自测说明有没有过</li></ul><p>所以如果把 <code>Intent</code>、<code>Change Set</code>、<code>Risk</code>、<code>Validation</code> 全部塞进每一条 commit message，最后很可能还是没人看。</p><p>它会变成另一种高级形式主义。</p><p>因此 Smart Commit 的方向不是让每条 commit 都变得很长，而是：</p><ul><li>commit 保持短，只记录这一小块是什么</li><li>一次推送结束后生成一份 Change Report</li><li>Change Report 放到 PR 描述里，成为人真正看的入口</li></ul><p>commit 是账本，PR 里的 Change Report 才是协作说明书。</p><h2 id="change-report-是什么" tabindex="-1">Change Report 是什么 <a class="header-anchor" href="#change-report-是什么" aria-label="Permalink to “Change Report 是什么”">​</a></h2><p>Change Report 不是 Git 原生就有的东西，也不是以前项目里已经存在的东西。</p><p>它是 Smart Commit 这个 skill 新增的一种输出约定。</p><p>每次 smart commit 执行完提交和推送后，都生成一段“本次变更报告”。</p><p>它大概长这样：</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Intent:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">本次推送整体想解决什么问题。</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Change Set:</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 改了哪些模块</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 每组变更解决什么问题</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Validation:</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 执行了哪些验证</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 哪些没验证，为什么</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Risk:</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 可能影响哪里</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 人需要重点看哪里</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Commits:</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> hash + commit message</span></span></code></pre></div><p>这个东西第一版可以只出现在 Codex 对话窗口里。</p><p>但更合理的是放进 PR 描述里。</p><p>因为人审代码的时候，本来就应该看 PR，而不是一条一条翻 commit。</p><h2 id="pr-流程为什么重要" tabindex="-1">PR 流程为什么重要 <a class="header-anchor" href="#pr-流程为什么重要" aria-label="Permalink to “PR 流程为什么重要”">​</a></h2><p>如果要让产品和 UI 也开始写代码，那 PR 流程就更重要了。</p><p>因为他们现在连分支的概念都不懂，也不知道创建分支，也不知道为什么我们需要创建分支。这些基本的概念都没有。</p><p>这不是他们的问题。</p><p>以前写代码是程序员的事情，所以 Git 的复杂性被默认丢给程序员消化。现在 AI 让产品、UI、运营都可能直接改代码，这些人不应该被要求先学完整套 Git。</p><p>但是他们也不能直接往主分支提交。</p><p>主分支可以理解成“大家现在共同依赖的稳定版本”。</p><p>分支可以理解成“我先在旁边开一个临时工作区”。我可以在这个工作区里让 AI 修改代码、生成页面、改样式、补文案。只要它还没有合并回主分支，就不会影响其他人。</p><p>PR 就是把这个临时工作区拿出来给别人看：</p><ul><li>我改了什么</li><li>为什么这么改</li><li>有没有验证</li><li>有没有风险</li><li>是否允许合并回主分支</li></ul><p>所以 PR 不是形式主义。</p><p>PR 是“把代码变更交给团队确认”的入口。</p><p>Smart Commit 要做的事情，就是把这些 Git 概念藏到后面，让产品和 UI 不需要先理解所有命令，也能走一条相对安全的协作路径。</p><p>他们只需要说：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>smart commit，走 PR 流程</span></span></code></pre></div><p>然后 Smart Commit 做这些事：</p><ol><li>如果当前在 <code>main</code>，自动创建一个 <code>codex/xxx</code> 分支</li><li>根据业务意图分析 diff</li><li>把相关文件分成几组 commit</li><li>推送分支到 GitHub</li><li>生成 Change Report</li><li>用 Change Report 创建 PR 描述</li></ol><p>这样，产品和 UI 不一定需要立刻懂 Git 的全部概念，但他们提交出来的东西依旧是团队可以审查、可以回滚、可以追踪的。</p><h2 id="它面向的用户是谁" tabindex="-1">它面向的用户是谁 <a class="header-anchor" href="#它面向的用户是谁" aria-label="Permalink to “它面向的用户是谁”">​</a></h2><p>Smart Commit 不是只面向资深程序员的。</p><p>它更像是给 AI Coding 时代的新协作者准备的。</p><p>第一类是程序员。</p><p>程序员当然懂 Git，但是现在 AI 一次性改很多文件，commit 容易变成流水账。Smart Commit 可以帮程序员把 diff 按业务意图拆开，再生成一份可以直接放进 PR 的说明。</p><p>第二类是产品和 UI。</p><p>他们已经开始直接写代码了。</p><p>他们可能不懂分支、不懂 commit、不懂 PR，但是他们懂需求、懂界面、懂用户体验。AI 帮他们把代码写出来以后，真正缺的是一条安全进入工程协作的路。</p><p>Smart Commit 对他们的价值不是“教会他们 Git”，而是先让他们用一种不容易把主分支搞坏的方式参与进来。</p><p>第三类是小团队。</p><p>小团队最容易出现一种情况：大家都知道 Git 很重要，但是流程太重没人执行；流程太轻又容易出事故。</p><p>Smart Commit 可以把流程收敛成一句话：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>把这次改动整理成 PR。</span></span></code></pre></div><p>剩下的分支、提交、推送、PR 描述，都交给工具完成。</p><h2 id="最后" tabindex="-1">最后 <a class="header-anchor" href="#最后" aria-label="Permalink to “最后”">​</a></h2><p>我现在越来越觉得，AI 时代不是把所有旧工具都删掉。</p><p>更重要的是怀疑以前所有固有的工作经验。</p><p>Git 还在，分支还在，commit 还在，PR 还在。</p><p>但是它们的重心变了。</p><p>以前我们围绕 commit 工作。</p><p>现在我们应该围绕任务意图工作。</p><p>以前我们要求人写规范的 commit。</p><p>现在我们应该让 AI 帮我们生成完整的 Change Report，让人把精力放在判断风险、验证结果、确认是否合并。</p><p>所以 Smart Commit 不是一个“自动提交工具”。</p><p>它更像是 AI Coding 时代的一层协作适配器。</p><p>它解决的不是 Git 命令太难的问题，而是：当越来越多不熟悉 Git 的人开始通过 AI 写代码时，我们如何让他们安全地进入团队协作流程。</p><p>这才是它真正要解决的问题。</p><h2 id="附件-smart-commit-skill-完整内容" tabindex="-1">附件：Smart Commit Skill 完整内容 <a class="header-anchor" href="#附件-smart-commit-skill-完整内容" aria-label="Permalink to “附件：Smart Commit Skill 完整内容”">​</a></h2><p>这份 skill 的完整内容已经拆成独立附件，不再直接铺在文章正文里。</p><ul><li><a href="/yoran-secret/attachments/smart-commit-skill.html">查看 Smart Commit Skill 附件页</a></li></ul><p>这个附件不出现在博客菜单里，只能通过文章里的链接，或者直接访问附件路由打开。</p>`,109)]))}const k=a(l,[["render",e]]);export{d as __pageData,k as default};
